// Country outlines (Natural Earth 50m, public domain), one static file per destination in public/shapes/<id>.json,
// generated by backend/pipeline/build_geo.py. Loaded on demand and cached, so only the selected country is fetched.

export type CountryShape = { type: "Feature"; geometry: unknown; properties: { id: string } };

const cache = new Map<string, CountryShape | null>();
const pending = new Map<string, Promise<CountryShape | null>>();

/** The outline if it has already been loaded, else null. */
export function getCountryShape(id: string | null | undefined): CountryShape | null {
  return id ? (cache.get(id) ?? null) : null;
}

/** Fetch (once) and cache the outline for a destination id. Resolves to null if it is missing. */
export function loadCountryShape(id: string): Promise<CountryShape | null> {
  if (cache.has(id)) return Promise.resolve(cache.get(id) ?? null);
  const inflight = pending.get(id);
  if (inflight) return inflight;
  const p = fetch(`/shapes/${encodeURIComponent(id)}.json`)
    .then((r) => (r.ok ? (r.json() as Promise<CountryShape>) : null))
    .catch(() => null)
    .then((shape) => {
      cache.set(id, shape);
      pending.delete(id);
      return shape;
    });
  pending.set(id, p);
  return p;
}
